    function run(uint dep, uint am, address logAddr) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (dep)); require(dep <= 1000000000000000000000000000000);
        require(address(this).balance >= dep);
        c.SetLogFile(logAddr); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;
        c.Deposit{value: dep}(); if (__ESBMC_reverted()) return;
        uint beforeCBal = address(c).balance;
        bool reverted;
        c.Collect(am); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        uint afterCBal = address(c).balance;
